// Reaches `net` through a helper private to the package.
import { netAddress, tcpConnect } from "nish:net";

const dial = (port: i32): boolean => {
  const addr: u8[] = [];
  return netAddress(addr, "127.0.0.1", port) >= 0 && tcpConnect(addr) >= 0;
};

export const fetchText = (port: i32): i32 => (dial(port) ? 1 : 2);
